blocos.codigo:
* { box-sizing: border-box; }

.cartao {
  width: 240px;
  padding: 16px;
  border: 1px solid #c9a967;
  margin: 12px;
  border-radius: 8px;
}

nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 12px 20px;
}

nav a {
  color: #f1dca6;
  text-decoration: none;
}

nav a:hover {
  text-decoration: underline;
}
